#pragma once
#include <stdbool.h>
typedef enum {PC_NET_REFRESH,PC_NET_SETUP,PC_NET_BOUND_CONTINUE,PC_NET_SAVE_HELLO,PC_NET_BIND_ACCEPT,PC_NET_BIND_REJECT,PC_NET_ROSTER_PAGE,PC_NET_BATCH_START,PC_NET_BATCH_RETRY,PC_NET_BATCH_DISMISS,PC_NET_MEMBER_PREVIOUS,PC_NET_MEMBER_NEXT,PC_NET_SINGLE_SUBMIT,PC_NET_FRIEND_START,PC_NET_FRIEND_CONFIRM,PC_NET_FRIEND_CANCEL,PC_NET_FRIEND_DONE,PC_NET_CHANGE_PREPARE,PC_NET_CHANGE_CANCEL,PC_NET_CHANGE_START,PC_NET_FRIEND_SHOWN,PC_NET_ATTENDANCE_RETURN,PC_NET_COMMAND_COUNT} pc_net_command_kind;
static inline bool pc_net_command_valid(pc_net_command_kind kind){return kind>=PC_NET_REFRESH&&kind<PC_NET_COMMAND_COUNT;}
